<?php
require_once __DIR__ . '/../_common.php';api_require_role('admin');
function adminGenderFo($v):string{$x=strtolower(trim((string)$v));if(in_array($x,['l','laki-laki','laki laki'],true))return'L';if(in_array($x,['p','perempuan'],true))return'P';throw new InvalidArgumentException('gender harus L atau P.');}
try{
 $m=api_allow_methods(['GET','POST','PUT','DELETE']);
 if($m==='GET'){$sql="SELECT id_akun,nama,email,no_telp,tanggal_lahir,gender,alamat,hari_kerja_mulai,hari_kerja_selesai,jam_mulai,jam_selesai,photo_profile,status_akun,created_at FROM akun WHERE role='fo'";if(isset($_GET['id_akun'])){$id=api_int($_GET['id_akun'],'id_akun');$s=$conn->prepare($sql.' AND id_akun=?');$s->bind_param('i',$id);}else{$q=trim($_GET['q']??'');if($q!=='')$sql.=' AND (nama LIKE ? OR email LIKE ?)';$sql.=' ORDER BY id_akun DESC';$s=$conn->prepare($sql);if($q!==''){$like='%'.$q.'%';$s->bind_param('ss',$like,$like);}}$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();if(isset($_GET['id_akun'])){if(!$rows)throw new OutOfBoundsException('Akun FO tidak ditemukan.');api_reply(200,true,'Data FO berhasil diambil.',$rows[0]);}api_reply(200,true,'Daftar FO berhasil diambil.',$rows);}
 $b=api_body();if($m==='DELETE'){$id=api_int($b['id_akun']??($_GET['id_akun']??null),'id_akun');$s=$conn->prepare("UPDATE akun SET status_akun='nonaktif' WHERE id_akun=? AND role='fo'");$s->bind_param('i',$id);$s->execute();$n=$s->affected_rows;$s->close();if(!$n){$s=$conn->prepare("SELECT id_akun FROM akun WHERE id_akun=? AND role='fo'");$s->bind_param('i',$id);$s->execute();$ok=api_one($s);$s->close();if(!$ok)throw new OutOfBoundsException('Akun FO tidak ditemukan.');}api_reply(200,true,'Akun FO dinonaktifkan.',['id_akun'=>$id,'status_akun'=>'nonaktif']);}
 $name=api_string($b['nama']??($b['nama_lengkap']??null),'nama',100);$email=api_string($b['email']??null,'email',100);$phone=api_string($b['no_telp']??($b['no_hp']??null),'no_telp',100);$address=api_string($b['alamat']??null,'alamat',10000);$birth=api_string($b['tanggal_lahir']??null,'tanggal_lahir',10);$gender=adminGenderFo($b['gender']??null);$startDay=strtolower(api_string($b['hari_kerja_mulai']??($b['hari_kerja_dari']??'senin'),'hari_kerja_mulai',10));$endDay=strtolower(api_string($b['hari_kerja_selesai']??($b['hari_kerja_sampai']??null),'hari_kerja_selesai',10));$start=api_string($b['jam_mulai']??'08:00','jam_mulai',8);$end=api_string($b['jam_selesai']??'16:00','jam_selesai',8);$photo=api_string($b['photo_profile']??null,'photo_profile',300,false);$password=api_string($b['password']??null,'password',255,false);$status=$b['status_akun']??'aktif';$days=['senin','selasa','rabu','kamis','jumat','sabtu','minggu'];if(!in_array($startDay,$days,true)||!in_array($endDay,$days,true))throw new InvalidArgumentException('Hari kerja tidak valid.');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$birth))throw new InvalidArgumentException('tanggal_lahir harus YYYY-MM-DD.');if(!in_array($status,['aktif','nonaktif'],true))throw new InvalidArgumentException('status_akun tidak valid.');
 if($m==='POST'){if(!$password)throw new InvalidArgumentException('password wajib untuk akun baru.');$hash=password_hash($password,PASSWORD_DEFAULT);$s=$conn->prepare("INSERT INTO akun(nama,email,password,role,tanggal_lahir,no_telp,gender,alamat,hari_kerja_mulai,hari_kerja_selesai,jam_mulai,jam_selesai,photo_profile,status_akun) VALUES(?,?,?,'fo',?,?,?,?,?,?,?,?,?,?)");$s->bind_param('sssssssssssss',$name,$email,$hash,$birth,$phone,$gender,$address,$startDay,$endDay,$start,$end,$photo,$status);$s->execute();$id=(int)$conn->insert_id;$s->close();api_reply(201,true,'Akun FO berhasil dibuat.',['id_akun'=>$id]);}
 $id=api_int($b['id_akun']??($_GET['id_akun']??null),'id_akun');$s=$conn->prepare('SELECT id_akun FROM akun WHERE id_akun=? AND role=\'fo\'');$s->bind_param('i',$id);$s->execute();$ok=api_one($s);$s->close();if(!$ok)throw new OutOfBoundsException('Akun FO tidak ditemukan.');
 $sql='UPDATE akun SET nama=?,email=?,tanggal_lahir=?,no_telp=?,gender=?,alamat=?,hari_kerja_mulai=?,hari_kerja_selesai=?,jam_mulai=?,jam_selesai=?,photo_profile=?,status_akun=?';if($password)$sql.=',password=?';$sql.=' WHERE id_akun=? AND role=\'fo\'';$s=$conn->prepare($sql);if($password){$hash=password_hash($password,PASSWORD_DEFAULT);$s->bind_param('sssssssssssssi',$name,$email,$birth,$phone,$gender,$address,$startDay,$endDay,$start,$end,$photo,$status,$hash,$id);}else{$s->bind_param('ssssssssssssi',$name,$email,$birth,$phone,$gender,$address,$startDay,$endDay,$start,$end,$photo,$status,$id);}$s->execute();$s->close();api_reply(200,true,'Data FO berhasil diperbarui.',['id_akun'=>$id]);
}catch(Throwable $e){api_db_error($e);}